{"path":"/tmp/check.py","content":"import csv
with open("outputs/t12_selected_matrix.csv", "r", newline="") as f:
    reader = csv.reader(f)
    rows = list(reader)

    indicator_cols = ["DE1001V", "DE1002V", "DE3001V", "DE3017V", "TT1003V", "TT1006V", "TT1007V", "TT1010V"]
    rates = {}
    for col in indicator_cols:
        count = sum(1 for r in rows if r[col] == "" or r[col] is None or r[col] == "")
        rate = count / len(rows) if rows else 0
        rates[col] = rate
        print(f"{col}: count={count}, rate={rate:.6f}")

    print(f"\nColumns with rate <= 0.30: {[c for c, r in rates.items() if r <= 0.30]}")

    col_counts = {}
    for col in indicator_cols:
        count = sum(1 for r in rows if r[col] != "" and r[col] is not None and r[col] != "")
        col_counts[col] = count

    print(f"\nRows with each indicator:")
    for col in sorted(col_counts.keys()):
        print(f"  {col}: {col_counts[col]}")
"}

